  39     try {
  40       const authorization = request.headers.get('Authorization');
  41       if (!authorization?.startsWith('Bearer ')) {
  42         return handleApiError({ message: 'Unauthorized: Missing token' }, 401);
  43       }
  44       const token = authorization.substring(7);
  45 
  46       const authRepo = container.resolve<any>(IAuthRepositoryToken);
  47       const authResult = await authRepo.verifyToken(token);
  48 
  49       if (authResult.isFailure) {
  50         return handleApiError({ message: 'Unauthorized: Invalid token' }, 401);
  51       }
  52 
  53       const decodedUser = authResult.getValue();
  54 
  55       const userRepo = container.resolve<any>(IUserRepositoryToken);
  56       const userResult = await userRepo.getById(decodedUser.uid);
  57 
  58       if (userResult.isFailure) {
