  10 
  11 export const runAuthenticatedClientCall = async <TClient, TResult>(
  12   firebaseUser: FirebaseUser | null | undefined,
  13   clientClass: ClientConstructor<TClient>,
  14   callback: (client: TClient, token: string) => Promise<TResult>,
