  21   const client = container.resolve(clientClass);
  22 
  23   return callback(client, token);
  24 };
  25 
  26 export const unwrapResult = <TValue, TError>(result: Result<TValue, TError>): TValue => {
  27   if (result.isFailure) {
  28     if (result.error instanceof Error) {
  29       throw result.error;
  30     }
  31 
