   3 export class ApiError extends Error {
   4   constructor(
   5     public message: string,
   6     public status: number,
   7     public details?: any
   8   ) {
   9     super(message);
  10     this.name = 'ApiError';
  11   }
  12 }
  13 
  14 interface ApiServiceOptions<T> {
  15   endpoint: string;
  16   method?: 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH';
  17   data?: T;
  18   token?: string; // Allow passing token directly
  19   headers?: Record<string, string>;
  20   isFormData?: boolean;
  21   responseType?: 'json' | 'blob' | 'text';
  22 }
  23 
  24 /**
  25  * A unified API service function to handle all client-server communication.
  26  * It automatically handles authentication, request body serialization, and response parsing.
  27  *
  28  * @param options - The configuration for the API request.
  29  * @returns A promise that resolves to the JSON response from the API.
  30  * @throws An ApiError if the request fails or the user is not authenticated when required.
  31  */
  32 export async function apiService<TRequest = any, TResponse = any>(
  33   options: ApiServiceOptions<TRequest>
  34 ): Promise<TResponse> {
  35   const {
  36     endpoint,
  37     method = 'GET',
  38     data,
  39     token: directToken,
  40     headers = {},
  41     isFormData = false,
  42     responseType = 'json',
  43   } = options;
  44 
  45   let authToken = directToken;
  46 
  47   const config: RequestInit = {
  48     method,
  49     headers: { ...headers },
  50   };
  51 
  52   if (authToken) {
  53     config.headers = {
  54       ...config.headers,
  55       'Authorization': `Bearer ${authToken}`,
  56     };
  57   }
  58 
  59   if (data) {
  60     if (isFormData) {
  61       // Don't set Content-Type for FormData, browser does it with boundary
  62       config.body = data as unknown as FormData;
  63     } else {
  64       (config.headers as Record<string, string>)['Content-Type'] = 'application/json';
  65       config.body = JSON.stringify(data);
  66     }
  67   }
  68 
  69   const response = await fetch(endpoint, config);
  70 
  71   if (!response.ok) {
  72     let errorData;
  73     try {
  74       errorData = await response.json();
  75     } catch {
  76       // If the response is not JSON, use the status text
  77       errorData = { message: response.statusText || 'An unknown error occurred.' };
  78     }
  79     throw new ApiError(errorData.message || response.statusText, response.status, errorData.details);
  80   }
  81 
  82   if (responseType === 'blob') {
  83     return (await response.blob()) as TResponse;
  84   }
  85 
  86   if (responseType === 'text') {
  87     return (await response.text()) as TResponse;
  88   }
  89 
  90   // Handle cases where the response might be empty (e.g., DELETE 204 No Content)
  91   const contentType = response.headers.get('content-type');
  92   if (contentType && contentType.includes('application/json')) {
  93     return response.json();
  94   }
  95   // Return an empty object or a success indicator for non-JSON responses
  96   return {} as TResponse;
  97 }
  98 
