  72       queryClient.invalidateQueries({ queryKey: projectKeys.lists(projectScope) });
  73       queryClient.invalidateQueries({ queryKey: projectKeys.detail(projectScope, savedProject.id ?? '') });
  74       toast({ title: 'Project Saved', description: `"${savedProject.name}" has been saved to the cloud.` });
  75     },
  76     onError: (error: unknown) => {
  77       const description = error instanceof Error ? error.message : 'Failed to save project.';
  78       toast({ title: 'Error', description: `Failed to save project: ${description}`, variant: 'destructive' });
  79     },
  80   });
  81 
  82   return {
  83     saveProjectMutation,
  84     isSaving: saveProjectMutation.isPending,
  85   };
