  88 export function useDeleteProject() {
  89   const queryClient = useQueryClient();
  90   const { firebaseUser } = useAuth();
  91   const projectScope = firebaseUser?.uid ?? 'anonymous';
  92 
  93   return useMutation({
  94     mutationFn: async (projectId: string) => {
  95       const localService = container.resolve(LocalProjectService);
  96       const localDelete = localService.deleteProject(projectId);
  97 
  98       if (navigator.onLine && firebaseUser) {
  99         try {
 100           await runAuthenticatedResultCall(firebaseUser, ProjectApiClient, (client, token) =>
 101             client.deleteProject(projectId, token),
 102           );
 103         } catch (error) {
 104           console.error('Failed to delete from server:', error);
 105         }
 106       }
 107 
 108       await localDelete;
 109       return projectId;
 110     },
 111     onSuccess: (projectId) => {
 112       toast({ title: 'Project Deleted', description: 'The project has been successfully deleted.' });
 113       queryClient.invalidateQueries({ queryKey: projectKeys.lists(projectScope) });
 114       queryClient.removeQueries({ queryKey: projectKeys.detail(projectScope, projectId) });
 115     },
 116     onError: (error: unknown) => {
 117       const description = error instanceof Error ? error.message : 'Delete failed.';
 118       toast({ title: 'Delete Failed', description, variant: 'destructive' });
 119     },
 120   });
 121 }
